    'N2': [(0.25, 195.0, 140.0), (0.50, 210.0, 140.0), (0.75, 225.0, 140.0)],
    'E2': [(0.25, 180.0, 150.0), (0.50, 180.0, 160.0), (0.75, 180.0, 170.0)],
}

station_elem_map = {}

for line, st_list in wall_line_stations.items():
    # Filter elements that have an edge on that wall line
    edge_elems = []
    for e_idx, (i, j, xc, yc, zid) in enumerate(elements):
        if line == 'S' and j == 0:
            edge_elems.append((e_idx, xc, yc))
        elif line == 'E' and (i + 1) * H == 240.0 and yc <= 140.0:
            edge_elems.append((e_idx, xc, yc))
        elif line == 'N1' and (j + 1) * H == 180.0 and xc <= 180.0:
            edge_elems.append((e_idx, xc, yc))
        elif line == 'W' and i == 0:
            edge_elems.append((e_idx, xc, yc))
        elif line == 'N2' and (j + 1) * H == 140.0 and xc >= 180.0:
            edge_elems.append((e_idx, xc, yc))
        elif line == 'E2' and (i + 1) * H == 180.0 and yc >= 140.0:
            edge_elems.append((e_idx, xc, yc))

    print(f"Line {line:3s}: found {len(edge_elems)} edge elements.")
    for frac, sx, sy in st_list:
        # find nearest element center
        best_e = min(edge_elems, key=lambda e: (e[1] - sx)**2 + (e[2] - sy)**2)
